-- ─────────────────────────────────────────────────────────────────────────────
-- portal_v29_onboarding_v2_catalogo.sql
--
-- GENERADO por scratchpad/gen-catalogo.cjs desde el fuente de
-- onboarding-korex-standalone.html. No editar a mano: para cambiar el catálogo
-- se usa el constructor de /admin/onboarding, que setea updated_by y por eso
-- queda protegido del `on conflict ... where updated_by is null` de abajo.
--
-- 4 bloques · 23 pasos · 125 preguntas
-- (93 obligatorias, 13 condicionales,
--  45 con micrófono, 62 con ejemplo)
--
-- El catálogo v1 (7 tramos / 66 preguntas) se DESACTIVA, no se borra:
-- onboarding_answers.qkey no tiene FK a propósito, así que las respuestas del
-- cliente de prueba sobreviven y simplemente dejan de contar para el progreso.
--
-- Además de las preguntas del HTML va una que no está en él: material_branding.
-- El paso 18 ofrece "Tengo logo, lo subo en PNG", "Tengo branding, lo adjunto"
-- y "Tengo tipografía, la subo a la carpeta", pero ninguna pantalla del
-- prototipo tiene dónde subirlo. Dejar tres promesas sin destino es peor que
-- agregar un dropzone opcional.
-- ─────────────────────────────────────────────────────────────────────────────

begin;

-- ── 1 · Baja el catálogo v1 ──────────────────────────────────────────────────
update public.onboarding_questions set activa = false, updated_at = now()
 where activa and skey in (select skey from public.onboarding_sections where bkey is null);
update public.onboarding_sections set activa = false, updated_at = now()
 where activa and bkey is null;

-- ── 2 · Bloques ──────────────────────────────────────────────────────────────
insert into public.onboarding_bloques (bkey, orden, nombre, corto, titulo, descripcion, desbloquea, activa) values
  ('b1', 10, 'Bloque 1 · Arranque', 'Arranque', 'Ya estás dentro, formalmente.', 'Tu sesión reservada, tus datos y tu contrato. Lo administrativo terminó — ahora viene lo que construye tu negocio.', '{}'::text[], true),
  ('b2', 20, 'Bloque 2 · Estrategia', 'Estrategia', 'Con esto ya podemos escribir tu VSL y tus anuncios.', 'Tu foco, tu oferta, tu gente y tu historia. Es el corazón del proyecto y ya está cerrado.', '{/guiones,/embudos}'::text[], true),
  ('b3', 30, 'Bloque 3 · Operación', 'Operación', 'Tu infraestructura queda lista para el día 0.', 'Dominio, WhatsApp, accesos y compliance. Todo lo que suele frenar un lanzamiento, resuelto de entrada.', '{}'::text[], true),
  ('b4', 40, 'Bloque 4 · Materiales y arranque', 'Materiales', 'Terminaste. Ahora empezamos nosotros.', '', '{/material}'::text[], true)
on conflict (bkey) do update set orden = excluded.orden, nombre = excluded.nombre, corto = excluded.corto,
  titulo = excluded.titulo, descripcion = excluded.descripcion,
  desbloquea = excluded.desbloquea, activa = true, updated_at = now()
 where public.onboarding_bloques.updated_by is null;

-- ── 3 · Pasos ────────────────────────────────────────────────────────────────
insert into public.onboarding_sections (skey, bkey, orden, badge, eyebrow, titulo, subtitulo, para_que, icono,
   una_por_pantalla, minutos, checkpoint, promesa, intro_md, activa) values
  ('p00', 'b1', 10, '00', 'Primero lo primero', 'Agenda tu sesión de onboarding', 'Reserva ahora la videollamada en la que repasamos todo esto contigo. Completa el resto del onboarding antes de esa reunión: la usamos para resolver dudas, no para responderlo ahí.', 'Reservar la llamada ahora te asegura el lugar en la agenda del equipo — y todo lo demás avanza en paralelo.', 'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z', false, 1, false, '', '', true),
  ('p01', 'b1', 20, '01', 'Sección 0 · datos administrativos', 'Empecemos por ti', 'Lo justo para formalizar el inicio: con estos datos armamos tu contrato y tu factura. Dos minutos y pasamos a lo importante.', 'Con esto emitimos tu contrato y tu factura, y no volvemos a molestarte con papeles.', 'M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8z', false, 7, false, '', '', true),
  ('p03', 'b2', 30, '03', 'Sección 1 · el rumbo', '¿Cuál es tu foco?', 'Solo una opción puede ser el foco principal. Esto ordena todo lo que viene: si eliges oportunidad, empezamos por ahí. Igual completarás lo básico del otro pilar para que entendamos tu empresa al 100%.', 'Define el mensaje principal de tus anuncios: producto u oportunidad, nunca los dos a la vez.', 'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM12 11.6a.4.4 0 1 0 0 .8.4.4 0 0 0 0-.8z', false, 1, false, '', '', true),
  ('p04', 'b2', 40, '04', 'Sección 2 · lo esencial', 'Tu negocio', 'Información general que aplica a ambos focos. Con esto entendemos qué haces y a quién ayudas.', 'Es la base de todo lo que vamos a escribir: qué haces y a quién ayudas.', 'M4 7h16a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2zM8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M2 12h20', false, 6, false, '', '', true),
  ('p05', 'b2', 50, '05', 'Sección 3 · tu gente', 'Tu equipo y comunidad', 'Aplica sobre todo si tu foco incluye oportunidad de negocio, pero complétala igual.', 'Alimenta el bloque de comunidad de tu video y filtra a quién queremos atraer.', 'M17 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9.5 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75', false, 11, false, '', '', true),
  ('p4a', 'b2', 60, '4A', 'Sección 4A · tu oferta de producto', 'Tu producto', 'Completa si tu foco incluye producto. Si es oportunidad 100%, danos al menos lo básico para entender tu empresa.', 'Con esto armamos tu oferta de producto y el avatar al que le hablan los anuncios.', 'M21 8l-9-5-9 5v8l9 5 9-5V8zM3 8l9 5 9-5M12 13v9', false, 20, false, '', '', true),
  ('p4b', 'b2', 70, '4B', 'Sección 4B · tu oferta de oportunidad', 'Tu oportunidad de negocio', 'Completa si tu foco incluye oportunidad. Si es producto 100%, danos al menos lo básico.', 'Con esto armamos tu oferta de oportunidad y el guion de reclutamiento.', 'M22 7l-8.5 8.5-4-4L2 19M16 7h6v6', false, 15, false, '', '', true),
  ('p06', 'b2', 80, '06', 'Nuevo · para no adivinar a mitad de camino', '¿Por qué frente empezamos?', 'Elegiste trabajar los dos pilares. Si de la estrategia salen dos avatares, saber cuál lanza primero nos evita frenar el diseño con consultas — y a ti, esperas.', 'Saber cuál lanza primero evita frenar el diseño para consultarte a mitad de camino.', 'M6 3v12M18 9a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM6 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM15 6H9a3 3 0 0 0-3 3v3', false, 1, false, '', '', true),
  ('p07', 'b2', 90, '07', 'Sección 5 · cómo suena tu marca', 'Comunicación y tono', 'Esto define cómo hablan tus anuncios — y qué nunca deben decir. Los claims que marques como prohibidos se convierten en un filtro que revisa cada anuncio antes de grabarlo, para que Meta no te rechace nada.', 'Define cómo suenan tus anuncios y activa el filtro que evita que Meta te rechace nada.', 'M3 11l18-5v12L3 14v-3zM11.6 16.8a3 3 0 1 1-5.8-1.6', false, 8, false, '', '', true),
  ('p08', 'b2', 100, '08', 'Sección 6 · el terreno', 'Competencia y diferenciadores', 'Nos ayuda a posicionarte con claridad frente a quien ya está ahí.', 'Nos posiciona con claridad frente a quien ya está en tu mercado.', 'M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1zM4 22v-7', false, 3, false, '', '', true),
  ('p09', 'b2', 110, '09', 'Sección 7 · la más importante de todas', 'Tu historia y autoridad', 'Esta sección alimenta tu autoridad y tu conexión con la audiencia — y la conexión vende. En vez de escribir, háblanos: graba cada respuesta como si te estuvieran entrevistando. Lo transcribimos palabra por palabra, sin pulir. Cuanto más real y con más datos concretos, mejor.', 'Es la materia prima de tu video de ventas: tus palabras, sin pulir, son las que venden.', 'M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3zM19 10v2a7 7 0 0 1-14 0v-2M12 19v3', true, 24, false, '', '', true),
  ('p10', 'b2', 120, '10', 'Sección 8 · tus formularios de captación', 'Calificación del lead', 'Define cómo filtramos a la gente que entra por tus anuncios.', 'Configura el formulario que la gente completa antes de llegar a tu WhatsApp.', 'M22 3H2l8 9.46V19l4 2v-8.54L22 3z', false, 3, false, '', '', true),
  ('p11', 'b2', 130, '11', 'Sección 9 · lo que ya probaste', 'Experiencias en marketing', 'Aprendemos de lo que ya funcionó y evitamos repetir lo que no.', 'Reutilizamos lo que ya te funcionó y evitamos repetir lo que te costó dinero.', 'M12 8v4l3 2M3.05 11a9 9 0 1 1 .5 4M3 4v5h5', false, 3, false, '', '', true),
  ('p12', 'b3', 140, '12', 'Sección 10 · tu activo más valioso', 'Audiencia y segmentación', 'Tu base de datos es oro: con ella Meta encuentra a personas parecidas a tus mejores clientes y baja tu coste por lead.', 'Tu base de datos y tu Pixel bajan el coste por lead desde la primera semana.', 'M12 3c4.97 0 9 1.34 9 3s-4.03 3-9 3-9-1.34-9-3 4.03-3 9-3zM3 6v12c0 1.66 4.03 3 9 3s9-1.34 9-3V6M3 12c0 1.66 4.03 3 9 3s9-1.34 9-3', false, 3, false, '', '', true),
  ('p13', 'b3', 150, '13', 'Sección 11 · tu operación actual', 'Canales, proceso y presupuesto', 'Cómo vendes hoy y con qué recursos cuentas.', 'Con esto calculamos tu inversión diaria y diseñamos el embudo sobre tu proceso real.', 'M4 21v-7M4 10V3M12 21v-9M12 8V3M20 21v-5M20 12V3M1 14h6M9 8h6M17 16h6', false, 8, false, '', '', true),
  ('p14', 'b3', 160, '14', 'Sección 12 · dónde vivirá tu landing', 'Tu dominio', 'Definir esto ahora nos deja congelar la URL el día 0 — y eso desbloquea todo el montaje en paralelo mientras tú sigues con lo tuyo.', 'Congelar la URL hoy nos deja montar tu landing en paralelo.', 'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zM3 12h18M12 3c2.5 2.5 3.6 5.5 3.6 9s-1.1 6.5-3.6 9c-2.5-2.5-3.6-5.5-3.6-9S9.5 5.5 12 3z', false, 7, false, '', '', true),
  ('p15', 'b3', 170, '15', 'Sección 13 · contacto directo', 'Tu WhatsApp', 'Este número irá en los botones de contacto de tu landing y tus anuncios. Verifícalo bien — un dígito mal cuesta leads.', 'Es el número al que van a llegar los interesados: un dígito mal cuesta leads.', 'M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z', false, 4, false, '', '', true),
  ('p16', 'b3', 180, '16', 'Nuevo · para no frenar el lanzamiento', 'Accesos a Meta y redes', 'Estos accesos suelen aparecer al final y frenan el lanzamiento días enteros. Los resolvemos ahora, de una vez, y tu campaña no espera a nadie.', 'Los accesos son lo que más retrasa lanzamientos. Resolverlos ahora te ahorra días.', 'M21 2l-2 2M11.4 11.6a5 5 0 1 1-7.1 7.1 5 5 0 0 1 7.1-7.1zM11.4 11.6L15.5 7.5M15.5 7.5l3 3L22 7l-3-3-3.5 3.5z', false, 7, false, '', '', true),
  ('p17', 'b3', 190, '17', 'Nuevo · el trámite que corre en paralelo', 'Compliance de tu empresa', 'Algunas empresas exigen aprobar la publicidad de sus distribuidores antes de publicarla — un trámite que puede tardar semanas. Si es tu caso, lo iniciamos HOY en paralelo, para que no frene nada.', 'Si tu empresa aprueba publicidad, el trámite arranca hoy en paralelo.', 'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10zM9 12l2 2 4-4', false, 6, false, '', '', true),
  ('p18', 'b4', 200, '18', 'Sección 14 · tu material', 'Sube tus archivos', 'Arrastra aquí lo que tengas. Se sube directo a tu carpeta. Lo que no tengas hoy lo marcas como pendiente y tu landing sale igual: la completamos en cuanto llegue (V1 → V2). Fecha límite de materiales: día 3.', 'Tu material es lo que hace que todo salga con tu identidad y tu cara.', 'M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M17 8l-5-5-5 5M12 3v12', false, 15, false, '', '', true),
  ('p19', 'b4', 210, '19', 'Nuevo · para no frenarnos cuando no estás', 'Tu delegado y tu comunicación', 'Sabemos que lideras y viajas mucho. Si tienes una persona de confianza que pueda decidir por ti en el día a día, el proyecto no se detiene cuando tú no puedes responder. Si trabajas solo, sáltate los tres primeros campos.', 'Una persona que pueda decidir por ti evita que el proyecto se detenga cuando viajas.', 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM16 11l2 2 4-4', false, 8, false, '', '', true),
  ('p20', 'b4', 220, '20', 'Sección 15 + agenda · lo que más acelera tu entrega', 'Tu grabación y HeyGen', 'Tu grabación es el único paso que solo puedes dar tú — todo lo demás lo adelantamos en paralelo. Reservándola ahora, tu reloj de 15 días arranca con fecha real. Y HeyGen nos permite generar anuncios sin pedirte grabar una y otra vez.', 'Tu grabación es el único paso que solo puedes dar tú. Reservarla pone fecha real al lanzamiento.', 'M23 7l-7 5 7 5V7zM14 5H3a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2z', false, 3, false, '', '', true),
  ('p21', 'b4', 230, '21', 'Último paso · el control de calidad', 'Revisemos que no falte nada', 'Tu reloj de 15 días solo arranca cuando lo crítico está completo. Esto es lo que tienes cerrado y lo que queda pendiente — lo pendiente no te frena, pero cuanto antes llegue, antes despega todo.', 'Repasamos qué está cerrado y qué falta antes de arrancar el reloj.', 'M22 11.08V12a10 10 0 1 1-5.93-9.14M22 4l-10 10-3-3', false, 1, false, '', '', true)
on conflict (skey) do update set bkey = excluded.bkey, orden = excluded.orden, badge = excluded.badge,
  eyebrow = excluded.eyebrow, titulo = excluded.titulo, subtitulo = excluded.subtitulo,
  para_que = excluded.para_que, icono = excluded.icono,
  una_por_pantalla = excluded.una_por_pantalla, minutos = excluded.minutos,
  checkpoint = excluded.checkpoint, activa = true, updated_at = now()
 where public.onboarding_sections.updated_by is null;

