   false, null, null, null, null, null, 'fill',
   1, 1, 607, '4A · Tu producto', '', true),
  ('producto_garantia', 'p4a', 0, 80, '¿Hay garantía? ¿Tiempo y condiciones?', '', '', '', '30 días de devolución. Si no está conforme, devuelve los envases aunque estén vacíos y se le reintegra el 100%. Lo cubre la empresa, no yo.', '',
