  ('av_prod_laboral', 'p4a', 0, 110, 'Situación laboral', '', '', '', 'Docentes, enfermeras, empleadas administrativas y algunas con un emprendimiento chico de comida o ropa. Casi todas con sueldo fijo que no les alcanza y doble jornada en casa.', 'Docentes, enfermeras, empleadas administrativas · sueldo fijo',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, true, 0, 0, null, '', 90,
