   1, 1, 611, '4A · Tu producto', '', true),
  ('av_prod_dolores', 'p4a', 0, 120, 'Dolores principales', 'Escríbelo como lo dice esa persona, no como lo dirías tú.', '', '', 'La mayoría llega diciendo lo mismo: «me miro al espejo y no me reconozco». Subieron 10 o 15 kilos después de los embarazos o de la menopausia, están todo el día cansadas, se levantan ya sin energía. Probaron de todo: la dieta de la nutricionista que abandonaron a la semana, el gimnasio al que fueron un mes, las pastillas que compraron por Instagram. Cada intento fallido les dejó la sensación de que el problema son ellas, que no tienen fuerza de voluntad. Y hay algo que casi ninguna dice en voz alta: dejaron de ir a eventos, de sacarse fotos, de tener intimidad con su pareja.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 130,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 612, '4A · Tu producto', '', true),
  ('av_prod_botones', 'p4a', 0, 130, 'Botones calientes — marca los que apliquen', '', '', '', '', '',
   '[]'::jsonb, 'chips_multi', '[{"value":"tiempo","label":"Tiempo extra","hint":""},{"value":"ingreso","label":"Ingreso extra","hint":""},{"value":"libertad","label":"Libertad financiera","hint":""},{"value":"viajar","label":"Viajar","hint":""},{"value":"desarrollo","label":"Desarrollo personal","hint":""},{"value":"jubilacion","label":"Jubilación","hint":""},{"value":"contribucion","label":"Contribución","hint":""}]'::jsonb, false, true, 0, 0, null, '', null,
