  ('av_op_dolores', 'p4b', 0, 90, 'Dolores principales', 'Sus palabras exactas, sin pulir.', '', '', '«Trabajo todo el día y no me alcanza.» «Estoy cansada de estar cansada.» «Quiero dejar de depender de mi sueldo.» «No tengo tiempo ni para mí.» «Me da vergüenza que mis amigas se enteren.» «¿Y esto realmente funciona o es como todo?» Y la que más duele: sienten que a esta altura de su vida ya no van a poder cambiar nada.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 130,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 709, '4B · Tu oportunidad de negocio', '', true),
  ('av_op_botones', 'p4b', 0, 100, 'Botones calientes — marca los que apliquen', '', '', '', '', '',
