   false, '{"qkey":"foco","in":["ambas_op","ambas_prod"]}'::jsonb, null, null, null, null, 'fill',
   1, 1, 801, '06 · ¿Por qué frente empezamos?', '', true),
  ('tono', 'p07', 0, 10, 'Ángulo y tono', 'Ej: formal, cercano, motivacional, analítico, comunidad que se apoya…', '', '', 'Cercano y directo, sin humo. Quiero que suene a una amiga que sabe de salud, no a una gurú. Me sirve el tono de comunidad («acá nadie se queda sola») y me molesta el tono de coach que grita. Nada de urgencia falsa.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 300, null, '', 100,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 901, '07 · Comunicación y tono', '', true),
  ('palabras_no', 'p07', 0, 20, 'Palabras o expresiones que NO quieres que aparezcan', '', '', '', 'No quiero «adelgazar», «dieta milagro», «cuerpo perfecto», «antes y después» como titular, ni nada que haga sentir mal a nadie por su cuerpo. Tampoco «libertad financiera en 6 meses»: me parece una falta de respeto.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 250, null, '', 100,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 902, '07 · Comunicación y tono', '', true),
  ('claims_si', 'p07', 0, 30, 'Claims o promesas PERMITIDOS por tu empresa', '', '', '', 'Se puede decir «ayuda a mejorar la digestión», «acompaña un estilo de vida saludable», «reemplazo de una comida». Se pueden mostrar testimonios si van con el descargo «resultados individuales».', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 250, null, '', 100,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 903, '07 · Comunicación y tono', '', true),
  ('claims_no', 'p07', 0, 40, 'Claims o promesas NO PERMITIDOS', 'Alimenta el filtro anti-baneo que revisa cada anuncio antes de grabarlo.', '', '', 'La empresa prohíbe decir «cura», «trata», «adelgaza» y mencionar cualquier enfermedad. No se pueden mostrar cifras de ingresos propias sin el descargo legal. No se puede usar el logo de la empresa en anuncios pagos. Y nada de «ingresos garantizados».', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 300, null, '', 110,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 904, '07 · Comunicación y tono', '', true),
  ('frases_cierre', 'p07', 0, 50, 'Frases que ya te funcionaron para cerrar gente', 'Escríbelas tal cual las dices, sin pulir — esto es oro puro para los anuncios.', '', '', '«No te estoy ofreciendo un trabajo más, te estoy ofreciendo dejar de pedir permiso.»
«Yo también pensé que era una estafa. Estuve seis meses evitando a la persona que me lo contó.»
«No necesitas saber vender, necesitas saber contar lo que te pasó.»
«¿Qué es lo peor que puede pasar? Que aprendas algo y no funcione. ¿Y lo mejor?»
«Si sigues igual dentro de un año, no va a ser por falta de una oportunidad.»', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 900, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 905, '07 · Comunicación y tono', '', true),
  ('objeciones', 'p07', 0, 60, 'Top 3-5 objeciones que más escuchas de prospectos', 'Cada objeción que nos cuentes la respondemos dentro de tu video.', '', '', '«Lo tengo que hablar con mi marido» es la número uno, y en realidad significa que no está convencida ella.
«No tengo tiempo», que me lo dicen justamente las que están más desesperadas por falta de tiempo.
«Yo no sirvo para vender» — la más fuerte en la parte de negocio: tienen miedo al ridículo delante de sus conocidos.
«¿Esto no es una pirámide?» — casi nadie lo dice así de frontal, lo insinúan.
«Ya probé de todo y nada me funcionó», que es más miedo a fracasar de nuevo que una objeción de precio.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 906, '07 · Comunicación y tono', '', true),
  ('competencia', 'p08', 0, 10, '¿Quiénes son tus principales competidores o referentes que te inspiran?', 'Nombres, cuentas o links. Uno por línea.', '', '', '@lauranutricion — misma empresa, España, muy buena en video
@vidaplenamlm — competencia directa, hacen mucho «antes y después»
Gabriela Ruiz — otra compañía, la referente del rubro en Argentina
Me inspira @doctormacarena por cómo explica sin vender', '@lauranutricion
@vidaplenamlm
Gabriela Ruiz',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, true, 0, 0, null, '', 110,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1001, '08 · Competencia y diferenciadores', '', true),
  ('ventajas', 'p08', 0, 20, '¿Qué ventajas competitivas quieres destacar frente a ellos?', '', '', '', 'Ellos venden el «baja 10 kilos en 10 días» y viven de la foto del antes y después. Yo quiero que se note que acá no hay milagro: hay un método de 30 días, un acompañamiento real y resultados que se sostienen. Y quiero destacar que soy enfermera, tengo formación en salud: no soy alguien que se puso a vender batidos de un día para el otro.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 500, null, '', 110,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1002, '08 · Competencia y diferenciadores', '', true),
  ('h1', 'p09', 0, 10, '¿A qué te dedicabas antes de este negocio? De dónde vienes', '', '', '', 'Trabajé 14 años como enfermera en un hospital público. Turnos de 12 horas, guardias los fines de semana, y aun así no me alcanzaba para pagar el alquiler y la escuela de mis dos hijos. Me levantaba a las 5 de la mañana y volvía cuando ya estaban dormidos. Llegué a tener tres trabajos: el hospital, cuidados a domicilio los sábados y vendía ropa por catálogo. Estaba agotada todo el tiempo y sentía que por más que trabajara, nunca iba a salir de ahí. Lo que más me dolía no era el dinero, era perderme la infancia de mis hijos.', '',
   '["a qué te dedicabas","cuántas horas trabajabas","qué te dolía de esa vida"]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 900, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1101, '09 · Tu historia y autoridad', '', true),
  ('h2', 'p09', 1, 10, '¿Hace cuánto iniciaste en el negocio que haces hoy?', '', '', '', 'Arranqué en marzo de 2019, así que van poco más de 7 años. Los primeros ocho meses fueron casi nulos, empecé a facturar en serio a fines de 2019.', 'Marzo de 2019, van 7 años',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, true, 0, 0, null, '', 90,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1121, '09 · Tu historia y autoridad', '', true),
  ('h3', 'p09', 2, 10, '¿Por qué empezaste? Cuenta tu dolor, tu botón caliente — con contexto real', 'Esta respuesta es la que abre tu video de ventas. No hace falta que suene bonito.', '', '', 'Fue en marzo de 2019. Mi hijo menor tuvo un problema de salud y necesitaba un tratamiento que no cubría la obra social. Costaba lo que yo ganaba en cuatro meses. Tuve que pedirle dinero prestado a mi hermana y todavía me acuerdo de la vergüenza que sentí. Esa noche entendí que el problema no era que trabajara poco, era que estaba cambiando tiempo por dinero y el tiempo se me estaba acabando. Una compañera del hospital me venía hablando del negocio hacía meses y yo la evitaba, pensaba que era una estafa. La llamé al día siguiente. Empecé sin creerla del todo, con miedo a que se rieran de mí, pero con la certeza de que no podía seguir como estaba.', '',
   '["qué pasó exactamente","cómo te sentías","qué te decidió"]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 1200, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1141, '09 · Tu historia y autoridad', '', true),
  ('h4', 'p09', 3, 10, '¿Qué resultados de dinero y materiales has logrado?', 'Con números concretos. Si tu empresa no permite mostrar cifras, igual cuéntanoslas: nosotros sabemos cómo decirlo sin romper la norma.', '', '', 'Hoy facturo entre 6.000 y 8.000 dólares por mes, con meses de 11.000 en campaña. Tengo mi casa propia desde hace dos años, la pagué con el negocio. Cambié el auto en 2024. El año pasado me llevé a mis dos hijos a Cancún, el primer viaje de mi vida en avión, y pagué todo sin pedirle dinero a nadie. También le pago la prepaga a mi mamá.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1161, '09 · Tu historia y autoridad', '', true),
  ('h5', 'p09', 4, 10, '¿Qué resultados NO materiales has logrado?', 'Lo que ganaste que no se compra. Suele ser lo que más conecta.', '', '', 'Dejé el hospital en enero de 2021 y ese día lloré en el estacionamiento. Hoy llevo a mis hijos al colegio todas las mañanas y los busco. Mi hija me dijo «mamá, ahora estás siempre» y esa frase vale más que cualquier cifra. Y cambió algo adentro mío: dejé de pedir permiso. Antes tenía que rogar por un franco para un acto escolar; hoy decido yo. Me volví alguien a quien otras mujeres le piden consejo, y eso no lo tenía.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1181, '09 · Tu historia y autoridad', '', true),
  ('h6', 'p09', 5, 10, '¿Qué estilo de vida te permitió? Cuenta una anécdota', 'Una escena concreta, con día y lugar. Las anécdotas se ven; los adjetivos no.', '', '', 'En octubre del año pasado mi hijo tenía el acto de fin de curso un martes a las 10 de la mañana. Antes eso era imposible: significaba pedir un franco tres semanas antes y que me lo negaran. Ese día lo llevé, me quedé en la primera fila, filmé todo y después nos fuimos a desayunar los tres. Volví a casa a las 12 y trabajé dos horas desde el celular. Eso es lo que cambió: no la casa ni el auto, es poder estar donde tengo que estar.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1201, '09 · Tu historia y autoridad', '', true),
  ('h7', 'p09', 6, 10, '¿Cuántas personas tienes en tu red?', '', '', '', '412 personas en total, unas 90 activas de verdad. En cuatro países: Argentina, Chile, México y España.', '412 en total, unas 90 activas, en 4 países',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, true, 0, 0, null, '', 90,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1221, '09 · Tu historia y autoridad', '', true),
  ('h8', 'p09', 7, 10, '¿Qué cualidades tienen mayoritariamente esas personas?', '', '', '', 'Son mujeres de 35 a 50, casi todas mamás, con trabajo pero sin margen. Muchas ya habían vendido algo antes: ropa por catálogo, tortas, cosmética. Tienen en común que no les da vergüenza ofrecer y que necesitan algo concreto: una deuda, un hijo que empieza la facultad. Y las mejores son las que preguntan mucho al principio.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 500, null, '', 120,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1241, '09 · Tu historia y autoridad', '', true),
  ('h9', 'p09', 8, 10, '¿A qué tipo de persona NO quieres en tu negocio?', '', '', '', 'A los que buscan hacerse ricos sin trabajar, los del «¿cuánto gano sin hacer nada?». Tampoco a los que ya están en otra compañía y cambian cada seis meses: rompen el equipo. No quiero menores de 25 en general. Y no quiero a los que vienen a discutir si esto es una estafa: no me interesa convencer a nadie.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 500, null, '', 120,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1261, '09 · Tu historia y autoridad', '', true),
  ('h10', 'p09', 9, 10, '¿A quién SÍ quieres en tu negocio?', '', '', '', 'Mujeres de 35 a 55, mamás, que trabajan en relación de dependencia o tienen un emprendimiento chico. En Argentina, Chile o Uruguay. Que sean activas en redes, que comenten cosas, no las que solo miran. Y sobre todo: gente que quiera resolver algo, no gente que quiera quejarse.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 600, null, '', 120,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1281, '09 · Tu historia y autoridad', '', true),
  ('h11', 'p09', 10, 10, '¿Puntos diferenciales frente a otras oportunidades similares?', 'Lo que hace que alguien se quede contigo y no con otro líder de la misma empresa.', '', '', 'Yo no desaparezco después de que firman. La mayoría te suma y te deja sola con un PDF. Tengo un grupo de WhatsApp donde respondo todos los días, una llamada grupal los martes a las 20h desde hace tres años, y a cada persona nueva la acompaño en sus primeras cinco ventas. Armé un manual propio de 40 páginas que no es material de la empresa, es mío. Y soy honesta con los números: no prometo millones en tres meses, digo exactamente cuánto tardé yo.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 900, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1301, '09 · Tu historia y autoridad', '', true),
  ('h12', 'p09', 11, 10, '¿Qué edad tienes?', '', '', '', '', '43',
   '[]'::jsonb, 'corta', '[]'::jsonb, false, true, 0, 0, null, 'numeric', null,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1321, '09 · Tu historia y autoridad', '', true),
  ('h13', 'p09', 12, 10, '¿Cómo le explicas a alguien, en breve, el negocio que haces?', 'Como se lo dirías a un vecino en el ascensor. Esto se convierte casi textual en uno de tus anuncios.', '', '', 'Le digo: ayudo a personas que están cansadas de cambiar horas por dinero a armar un ingreso desde el celular, sin dejar lo que hacen hoy. Trabajo con una empresa de nutrición que tiene 30 años en el mercado, y lo que hago es enseñarle a la gente a vender esos productos y a formar su propio equipo. No es magia ni es rápido: al principio le dedicas una hora por día y en seis meses, si le pones, ya tienes un ingreso que se nota. Yo empecé igual, trabajando de enfermera.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 600, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1341, '09 · Tu historia y autoridad', '', true),
  ('h14', 'p09', 13, 10, '¿Algo más que quieras que sepamos?', 'Lo que no te preguntamos y crees que importa.', '', '', 'Dos cosas. Una: no quiero que se me venda como «la enfermera que se hizo rica», porque no es verdad y me da vergüenza. Prefiero «la enfermera que dejó el hospital». Y dos: mi hija mayor tiene 16 y a veces aparece en mis videos; me gustaría que no se use su cara en anuncios pagos.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, false, 0, 600, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1361, '09 · Tu historia y autoridad', '', true),
  ('aut_hitos', 'p09', 14, 10, 'Hitos, premios, entrevistas, conferencias', '', 'Autoridad pública', 'Lo usamos en la introducción de tu video. No te achiques: acá corresponde contar lo que lograste.', 'Soy rango diamante desde 2023. Gané el premio a mejor equipo del país en 2024. Hablé en el escenario del evento anual de la empresa en Miami el año pasado, delante de 4.000 personas.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 250, null, '', 110,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1381, '09 · Tu historia y autoridad', '', true),
  ('aut_medios', 'p09', 14, 20, 'Apariciones en medios, podcasts, eventos', '', '', '', 'Me entrevistaron en el programa de la mañana de Radio 2 de Rosario (dos veces), y estuve en el podcast «Mujeres que Facturan» en 2024. Nada de TV todavía.', 'Radio 2 Rosario (2 veces) · podcast Mujeres que Facturan, 2024',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, false, 0, 0, null, '', 100,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1382, '09 · Tu historia y autoridad', '', true),
  ('aut_reconocimientos', 'p09', 14, 30, 'Reconocimientos en la empresa o industria', '', '', '', 'Top 10 de facturación del país tres años seguidos. Reconocimiento «Líder Formadora» 2024 por cantidad de personas que subieron de rango en mi equipo. Y soy una de las 12 personas del consejo de líderes de la compañía en Argentina.', 'Top 10 de facturación del país 3 años seguidos · Líder Formadora 2024',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, false, 0, 0, null, '', 100,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1383, '09 · Tu historia y autoridad', '', true),
  ('objetivo_lead', 'p10', 0, 10, '¿Cuál es tu objetivo actual?', '', '', '', '', '',
   '[]'::jsonb, 'opciones', '[{"value":"volumen","label":"Más volumen","hint":"Atraer más leads aunque sean menos cualificados"},{"value":"calidad","label":"Más calidad","hint":"Cualificar en el embudo: llegan menos pero mejores al cierre"}]'::jsonb, false, true, 0, 0, null, '', null,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1201, '10 · Calificación del lead', '', true),
  ('preguntas_lead', 'p10', 0, 20, '¿Qué preguntas te ayudarían a cerrar más fácil cuando el prospecto llega?', 'Dos o tres. Las ponemos en el formulario que completan antes de contactarte.', '', '', '¿Hace cuánto que estás intentando resolver esto?
¿Cuánto podrías invertir por mes en tu salud o en tu negocio?
¿Cuántas horas por día le podrías dedicar?
¿Estás en Argentina, Chile o Uruguay?', '¿Hace cuánto que intentas resolver esto?
¿Cuánto podrías invertir por mes?
¿Cuántas horas al día le dedicarías?',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, true, 0, 0, null, '', 120,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1202, '10 · Calificación del lead', '', true),
  ('camp_ok', 'p11', 0, 10, '¿Alguna campaña que te haya dado BUENOS resultados?', 'Cuéntanos al detalle cómo la hicieron. Si nunca hiciste, dilo.', '', '', 'Hice un sorteo en Instagram en 2023 que me trajo 300 seguidores y 12 ventas. El anuncio era un video mío hablando a cámara contando mi caso, sin producción, grabado con el celular en la cocina. Gasté 80 dólares en 10 días. Lo que creo que funcionó fue que no parecía publicidad.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, false, 0, 350, null, '', 120,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1301, '11 · Experiencias en marketing', '', true),
  ('camp_no', 'p11', 0, 20, '¿Campañas que NO dieron resultados?', 'Por encima, qué errores se cometieron.', '', '', 'Puse 200 dólares en anuncios con una foto del producto y el precio. Cero ventas. Después entendí que a nadie le importa el producto, les importa lo que les pasa a ellas. También probé con una agencia que me hizo videos muy producidos y no funcionaron: se veían a kilómetros que eran un anuncio.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, false, 0, 300, null, '', 110,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1302, '11 · Experiencias en marketing', '', true),
  ('bbdd', 'p12', 0, 10, '¿Tienes bases de datos de emails o teléfonos de clientes?', 'Con ellas creamos audiencias «similares» y llegamos más fácil al público correcto.', '', '', '', '',
   '[]'::jsonb, 'opciones', '[{"value":"si","label":"Sí, la subo a mi carpeta","hint":""},{"value":"ayuda","label":"Sí, pero necesito ayuda para exportarla","hint":""},{"value":"no","label":"No tengo","hint":""}]'::jsonb, false, true, 0, 0, null, '', null,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1401, '12 · Audiencia y segmentación', '', true),
  ('pixel', 'p12', 0, 20, '¿Tienes Pixel de Meta o eventos de conversión instalados?', '', '', '', '', '',
   '[]'::jsonb, 'opciones', '[{"value":"si","label":"Sí, ya instalado","hint":""},{"value":"no","label":"No / no lo sé","hint":"Nosotros lo configuramos"}]'::jsonb, false, true, 0, 0, null, '', null,
