   false, null, null, null, null, null, 'fill',
   1, 1, 1501, '13 · Canales, proceso y presupuesto', '', true),
  ('proceso_venta', 'p13', 0, 20, '¿Cómo es tu proceso de ventas completo, de desconocido a cliente?', '', '', '', 'Me escriben por Instagram o WhatsApp, casi siempre preguntando el precio. Yo no doy precio de entrada: les hago tres preguntas para entender qué les pasa. Si veo que califica, le mando un audio de dos minutos contándole mi caso y le propongo una videollamada de 20 minutos. En la llamada le muestro el plan, le cuento testimonios parecidos al suyo y ahí sí le paso el precio. Cierro alrededor del 40% de las llamadas. A las que no cierran las paso a una lista y les mando contenido una vez por semana; varias compran dos o tres meses después.', '',
   '[]'::jsonb, 'abierta', '[]'::jsonb, true, true, 0, 700, null, '', 180,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1502, '13 · Canales, proceso y presupuesto', '', true),
  ('quien_graba', 'p13', 0, 30, '¿Quién graba los anuncios?', '', '', '', '', '',
   '[]'::jsonb, 'opciones', '[{"value":"yo","label":"Yo","hint":""},{"value":"equipo","label":"Alguien de mi equipo","hint":""},{"value":"ia","label":"Quiero que lo haga la IA","hint":""}]'::jsonb, false, true, 0, 0, null, '', null,
   '', '', '', '', '', '', true,
   false, null, null, null, null, null, 'fill',
   1, 1, 1503, '13 · Canales, proceso y presupuesto', '', true),
  ('lead_magnet', 'p13', 0, 40, '¿Tienes algo gratis para regalar?', 'Un PDF, una clase, una guía. Si no tienes, lo armamos nosotros.', '', '', 'Tengo una guía en PDF de 7 días de desayunos saludables que armé yo, la uso en Instagram y funciona bien. También hago un reto de 5 días por WhatsApp dos veces al año.', 'Guía en PDF de 7 días de desayunos saludables',
   '[]'::jsonb, 'abierta', '[]'::jsonb, false, false, 0, 0, null, '', 90,
   '', '', '', '', '', '', true,
